        'LIGHT_GREEN',
        'BLUE',
        'LIGHT_BLUE',
        'CYAN',
        'LIGHT_CYAN',
        'INDIGO',
        'LIGHT_INDIGO',
        'PURPLE',
        'LIGHT_PURPLE',
