export const getRecordHistory = {
  name: 'distru-get-record-history',
  title: 'Get a record’s history',
  kind: 'read',
  reaches: [],
  summary: 'Shows who changed a record, when, and what they changed.',
  description:
    "A record's history, as on its History tab: who changed it and when, what each field was before and after, and old notes, calls, meetings and emails logged on it. One CHANGE entry per action (a save, import, sync, job or automation run), with the rows of the record and its lines it wrote (the record's own row first; the first 50 when truncated). rowCount counts rows after netting each row's changes in the action, so it can be lower than distru-search-activity's. Values are raw (ids, numbers, enum values). A reference is {id, name}: name is its current name, null once the record is deleted or archived; no id when the MCP takes that type's ids nowhere or it is another company's (a menu buyer's account, user or locations). A field customFields.<id> is that custom field, named in label. A field with legacyText was copied from the old activity feed: its name is that feed's, and legacyText holds its text. An entry shows only this record's part of an action: for everything the action changed, pass its id to distru-search-activity ids. For changes across the company, use distru-search-activity. A page can hold fewer entries than limit, even none, while hasMore is true: keep following nextCursor. Errors as not found when no record of recordType matches recordId (another company's included); a permission error if the caller can't view it, its team restrictions included.",
  doc: 'docs/research/mcptools/get-record-history.md',
  input: z.object({
    limit: z.number().int().min(1).max(100).describe('Default: `10`').optional(),
    cursor: z.string().describe('nextCursor of the previous call; keep the other arguments unchanged.').optional(),
    recordType: z.enum([
      'ASSEMBLY',
      'AUTOMATION',
      'BATCH',
      'BIN',
      'CHARGE_PRESET',
      'COMPANY',
      'COMPANY_GROUP',
      'COMPLIANCE_TRANSFER',
      'COST_TYPE',
      'CREDIT',
      'CUSTOM_VALIDATION',
      'DATASET',
      'DRIVER',
      'HARVEST',
      'INVITATION',
      'INVOICE',
      'LABEL_TEMPLATE',
      'MENU',
      'SALES_ORDER',
      'PACKAGE',
      'PAYMENT_METHOD',
      'PAYMENT_TERM',
      'PLANT',
      'PLANT_GROUP',
      'PRICE_TIER',
      'PRODUCT',
      'PRODUCT_CATEGORY',
      'PRODUCT_GROUP',
      'PURCHASE',
      'RELATIONSHIP_TYPE',
      'RETURN',
      'ROLE',
      'SCHEDULED_ALERT',
      'STOCK_TRANSFER',
      'STRAIN',
      'TAG',
      'TAX',
      'TEAM',
      'TEARDOWN',
      'TEST_RESULT',
      'UNIT_TYPE',
      'USER',
      'VEHICLE',
    ]),
    recordId: z
      .string()
      .describe(
        "The record's ID, of recordType's kind: from that kind's search tool where one exists (e.g. distru-search-sales-orders, distru-search-products, distru-search-lookups), or a reference's id in another history entry. COMPLIANCE_TRANSFER, CUSTOM_VALIDATION, DATASET, DRIVER, INVITATION, LABEL_TEMPLATE, ROLE, SCHEDULED_ALERT, TEAM and VEHICLE ids come only from references.",
      ),
    sortBy: z
      .object({
        direction: z.enum(['ASC', 'DESC']),
        field: z.enum(['CHANGED_AT']).describe('CHANGED_AT: when the action started, or the note was logged.'),
      })
      .describe('Default CHANGED_AT DESC, newest first.')
      .optional(),
  }),
} satisfies DistruToolDef;

