export const searchMetrcActivities = {
  name: 'distru-search-metrc-activities',
  title: 'Search Metrc sync history',
  kind: 'read',
  reaches: [],
  summary: 'Searches Metrc activities — the changes Distru sends to Metrc.',
  description:
    "Searches Metrc activities — the changes Distru sends to Metrc. When a user makes a change in Distru that Metrc must also record (e.g. creating, adjusting or moving a package), Distru saves it and queues an activity that syncs in the background. Each license's activities sync one at a time, in creation order; a failed one holds back every later activity of its license until it is retried or undone, so a license has at most one FAILED activity at a time. Use it to find why a change isn't in Metrc yet, what is blocking a license's sync, or what is still queued. lastError is the latest error from sending it, null once it syncs. The package and assembly are null when there is none or the caller cannot see it.",
  doc: 'docs/research/mcptools/search-metrc-activities.md',
  input: z.object({
    limit: z.number().int().min(1).max(100).describe('Default: `10`').optional(),
    cursor: z.string().describe('nextCursor of the previous call; keep the other arguments unchanged.').optional(),
    assemblyIds: z.array(z.string()).describe('Resolve via distru-search-assemblies.').optional(),
    createdDateAfter: z
      .string()
      .describe('Inclusive. YYYY-MM-DD (start of day, company timezone) or ISO 8601 with a UTC offset.')
      .optional(),
    createdDateBefore: z
      .string()
      .describe('Inclusive. YYYY-MM-DD (end of day, company timezone) or ISO 8601 with a UTC offset.')
      .optional(),
    creatorIds: z.array(z.string()).describe('Resolve via distru-search-users.').optional(),
    ids: z.array(z.string()).optional(),
    licenseIds: z.array(z.string()).describe('Resolve via distru-search-licenses.').optional(),
    packageIds: z
      .array(z.string())
      .describe(
        'Activities acting on, creating (as assembly output), moving, or packaging plant batches into these packages. Resolve via distru-search-packages.',
      )
      .optional(),
    sortBy: z
      .object({ direction: z.enum(['ASC', 'DESC']), field: z.enum(['INSERTED_AT']) })
      .describe('Default INSERTED_AT DESC.')
      .optional(),
    statuses: z.array(z.enum(['QUEUED', 'FAILED', 'COMPLETED'])).optional(),
  }),
} satisfies DistruToolDef;

export const emailPdf = {
  name: 'distru-email-pdf',
  title: 'Email a PDF',
  kind: 'write',
  reaches: ['email'],
  summary: 'Emails one of those PDFs as an attachment, with the same email the Distru web app sends.',
  description:
    'Generates a Distru PDF — the same documents as distru-download-pdf — and emails it as an attachment, with the email the Distru web app sends for that document (a generic document email for assemblies). To get a link instead, use distru-download-pdf. The email is queued, not confirmed delivered; `emailedTo` lists the addresses it was queued to. Except for a Metrc manifest, the same permissions as emailing the PDF in the Distru web app apply; assemblies and batch, package and test result COAs, which the web app cannot email, need the permission to download them instead.',
  doc: 'docs/research/mcptools/email-pdf.md',
  input: z.object({
    document: z
      .enum([
        'INVOICE',
        'INVOICE_COA',
        'SALES_ORDER',
        'SALES_ORDER_COA',
        'PURCHASE_ORDER',
        'ASSEMBLY',
        'BATCH_COA',
        'PACKAGE_COA',
        'TEST_RESULT_COA',
        'METRC_MANIFEST',
      ])
      .describe(
        "Which PDF to generate. INVOICE: the invoice. INVOICE_COA: the invoice's COA (Certificate of Analysis) — the lab result file of the primary test result of each line item's batch and package, duplicates removed, combined into one PDF. SALES_ORDER: the sales order's order slip. SALES_ORDER_COA: the sales order's COA, combined from its line items the same way. PURCHASE_ORDER: the purchase order. ASSEMBLY: the assembly's work order. BATCH_COA / PACKAGE_COA: the lab result file of the batch's / package's primary test result. TEST_RESULT_COA: that test result's lab result file. A COA errors when it finds no lab result file. METRC_MANIFEST: the Metrc transfer manifest, fetched from Metrc with the user's Metrc API key for the manifest's license; it errors when the user has no working key for that license. No Distru permission applies.",
      ),
    id: z
      .string()
      .describe(
        'ID of the entity `document` is for. INVOICE, INVOICE_COA: invoice ID ("inv_…"), resolve via distru-search-invoices. SALES_ORDER, SALES_ORDER_COA: sales order ID ("so_…"), resolve via distru-search-sales-orders. PURCHASE_ORDER: purchase order ID ("po_…"), resolve via distru-search-purchase-orders; draft purchase orders are refused. ASSEMBLY: assembly ID ("asm_…"), resolve via distru-search-assemblies. BATCH_COA: batch ID ("batch_…"), resolve via distru-search-batches; deleted batches are not found. PACKAGE_COA: package ID ("pkg_…"), resolve via distru-search-packages. TEST_RESULT_COA: test result ID ("test_…"), resolve via distru-search-test-results. METRC_MANIFEST: Metrc manifest number, e.g. 0000012345, resolve via distru-search-metrc-manifests.',
      ),
    emailAddresses: z
      .array(z.string())
      .describe(
        "Never picked by the tool: for an invoice, distru-search-companies returns the customer's invoiceEmail; otherwise ask the user. distru-get-me returns the user's own email.",
      ),
  }),
} satisfies DistruToolDef;

